use std::{env,fs};use wasmc_json_component::{Lib,wasmtime};use wasmc_json_component::exports::wasmc::json::document::{Edit,EditKind};use wasmtime::{Engine,Store};use wasmtime::component::{Component,Linker};
fn main(){let args:Vec<_>=env::args().collect();let e=Engine::default();let c=Component::new(&e,fs::read(&args[1]).unwrap()).unwrap();let mut s=Store::new(&e,());let lib=Lib::instantiate(&mut s,&c,&Linker::new(&e)).unwrap();let d=lib.wasmc_json_document();let edits=[Edit{kind:EditKind::Set,path:"/b/-".into(),value_json:"true".into()},Edit{kind:EditKind::Remove,path:"/a".into(),value_json:"".into()}];assert_eq!(d.call_edit_or_bytes(&mut s,b"{\"a\":1,\"b\":[]}",&edits,"fallback").unwrap(),"{\"b\":[true]}");assert_eq!(d.call_edit_or_bytes(&mut s,b"invalid",&edits,"fallback").unwrap(),"fallback");let long=format!("{{\"a\":1,\"b\":[],\"x\":\"{}\"}}","z".repeat(3145728));let result=d.call_edit_or_bytes(&mut s,long.as_bytes(),&edits,"fallback").unwrap();assert_eq!(result,format!("{{\"b\":[true],\"x\":\"{}\"}}","z".repeat(3145728)));assert_eq!(d.call_edit_or_bytes(&mut s,b"{\"a\":1,\"b\":[]}",&edits,"fallback").unwrap(),"{\"b\":[true]}");println!("{{\"accepted\":true,\"engine\":\"wasmtime-component\",\"same_instance\":true,\"large_input_bytes\":3145728,\"fallback\":true}}");}
